import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
    @interface Tx {}

    interface Api {
        void publicTx();
    }

    static final AtomicInteger INTERCEPTED = new AtomicInteger();

    static class ApiImpl implements Api {
        @Tx public void publicTx() { }
        // 非 public 的 @Tx 方法：代理链上看不到它
        @Tx void packageTx() { }
        @Tx private void privateTx() { }
    }

    static class Handler implements InvocationHandler {
        private final Object target;
        Handler(Object t) { this.target = t; }
        public Object invoke(Object proxy, Method m, Object[] args) throws Throwable {
            Method impl = target.getClass().getMethod(m.getName(), m.getParameterTypes());
            if (impl.isAnnotationPresent(Tx.class)) INTERCEPTED.incrementAndGet();
            return m.invoke(target, args);
        }
    }

    public static void main(String[] args) throws Exception {
        ApiImpl impl = new ApiImpl();
        Api proxy = (Api) Proxy.newProxyInstance(
                Api.class.getClassLoader(), new Class<?>[]{Api.class}, new Handler(impl));

        INTERCEPTED.set(0); proxy.publicTx();
        System.out.println("public @Tx via proxy  -> intercepted: " + (INTERCEPTED.get() == 1));

        boolean exposed = false;
        for (Method m : Api.class.getMethods()) if (m.getName().equals("packageTx")) exposed = true;
        System.out.println("package-private method exposed on interface Api: " + exposed);

        boolean privDeclaredPublic = false;
        for (Method m : ApiImpl.class.getDeclaredMethods())
            if (m.getName().equals("privateTx")) privDeclaredPublic = Modifier.isPublic(m.getModifiers());
        System.out.println("private @Tx method is public: " + privDeclaredPublic);
        System.out.println("=> non-public @Tx methods never go through the proxy, tx disabled");
    }
}
